/* Partner Weixin photo intake, simulated in this page only. No messages are sent. */
'use strict';
const WX_SCENARIOS={clear:'清晰单题',multi:'一图多题',subject:'科目待确认',blur:'模糊补拍',duplicate:'同图重发',failed:'接收失败'};
let wxInput='weixin',wxAuto=true,wxLinked={'7':true,'5':true},wxSequence=0;
const wxCollections=new Map();
function wxStudent(g=grade){return g==='5'?'小满':'小禾';}
function wxState(){if(!wxCollections.has(grade))wxCollections.set(grade,{scenario:'clear',phase:'idle',receipt:null,drafts:[],selected:0,ackFailed:false,reshoot:false,notice:''});return wxCollections.get(grade);}
function resetWxDemo(){wxCollections.clear();wxAuto=true;wxLinked={'7':true,'5':true};wxInput='weixin';wxSequence=0;}
function wxSourceLine(q,full=false){const source=q.source==='微信 · 小知'?q:q.additionalSources?.at(-1);if(!source)return '';return '<div class="wx-source-line">'+icon('MessageCircle')+'<span>微信 · 小知 · '+(source===q?'首次收到 ':'补充来源收到 ')+esc(source.firstReceivedAt)+(full?'<br>原图随来源保留 · 收题记录 '+esc(source.receiptId)+' · 归属 '+esc(wxStudent(q.grade))+'自己的学习空间'+(source!==q?'<br>本次只追加来源，保留题目最初收录时间与复习历史。':''):'')+'</span></div>';}
function inboxView(){return heading(wxInput==='weixin'?'微信拍下来，这里接着学。':'拍下来，先替你收好。','和伙伴说一声、发张图。原图先保存，核对之后进入同一本错题本。','<button class="btn" id="wx-settings">'+icon('Settings')+'伙伴收题设置</button>','ONE PHOTO, ONE LEARNING JOURNEY')+'<div class="wx-entry-tabs" aria-label="收题入口"><button data-wx-input="weixin" class="'+(wxInput==='weixin'?'active':'')+'" aria-pressed="'+(wxInput==='weixin')+'">'+icon('MessageCircle')+'伙伴微信收题<span>私聊发图，自动留存</span></button><button data-wx-input="web" class="'+(wxInput==='web'?'active':'')+'" aria-pressed="'+(wxInput==='web')+'">'+icon('Upload')+'网页本地选图<span>直接上传，核对入库</span></button></div>'+(wxInput==='weixin'?weixinView():localInboxView());}
function weixinView(){const s=wxState();return '<div class="wx-binding-strip"><span class="wx-partner-icon">'+icon('MessageCircle')+'</span><div><strong>小知 · 个人微信伙伴</strong><p>'+(wxLinked[grade]?'已绑定发图人 → '+wxStudent()+'自己的学习空间（示例）':'当前示例账号未绑定，图片不会进入任何孩子的错题库')+'</p></div><span class="tag '+(wxAuto?'green':'amber')+'">'+(wxAuto?'自动收题已开启':'仅指令收题')+'</span><button class="text-btn" id="wx-settings-inline">设置 '+icon('ChevronRight')+'</button></div><div class="wx-workspace"><section class="panel wx-chat-panel"><div class="panel-head"><div><h2>在微信，发给学习伙伴</h2><p>模拟会话 · 不会发送真实微信消息</p></div><span class="tag">私聊</span></div><div class="wx-scenarios" aria-label="微信收题场景">'+Object.entries(WX_SCENARIOS).map(([value,label])=>'<button class="chip '+(s.scenario===value?'active':'')+'" data-wx-scenario="'+value+'" aria-pressed="'+(s.scenario===value)+'">'+label+'</button>').join('')+'</div><div class="wx-chat"><div class="wx-chat-top"><span class="wx-partner-avatar">知</span><div><strong>小知 · 学习伙伴</strong><p>'+wxStudent()+'的绑定私聊 · 示例</p></div></div><div class="wx-conversation" aria-live="polite">'+wxConversation(s)+'</div><div class="wx-compose">'+wxCompose(s)+'</div></div><p class="wx-demo-note">切换场景会开始一段新示例；已加入错题库的记录会保留。所有回执均为本页模拟。</p></section><section class="wx-web-side" id="wx-web-side" tabindex="-1" aria-live="polite">'+wxReceipt(s)+'</section></div><div class="wx-scope-note">'+icon('ShieldCheck')+'微信收题与网页上传共用错题、标签和复习历史。收到照片、发出回执、确认题目、验证掌握分别记录。</div>';}
function wxConversation(s){let html='<div class="wx-time">今天 19:42 · 演示会话</div>';if(s.phase==='idle')return html+'<div class="wx-message"><span class="wx-chat-avatar">知</span><div class="wx-bubble">把需要再学一次的题拍下来，发给我。原图先替你收好，再去网页核对和复习。</div></div><div class="wx-chat-empty">选一个场景，试着发来一道错题。</div>';
html+='<div class="wx-message mine"><span class="wx-chat-avatar">我</span><div class="wx-bubble wx-attachment">'+icon('Image')+'<strong>题目照片 · 1 张</strong><span>'+WX_SCENARIOS[s.scenario]+' · 模拟附件</span>'+(s.receipt?.explicit?'<span class="wx-command">/错题</span>':'')+'</div></div>';
let reply='';if(s.phase==='unlinked')reply='还没有绑定学习账号。请先在网页获取绑定码，发送 /link 绑定码完成绑定，再重新发送这张照片。';else if(s.phase==='ordinary')reply='本次未开启自动收题，图片仍按普通聊天处理。要单次收录，请在图片消息附上 /错题 或“加入错题本”。';else if(s.phase==='failed')reply='这张图片暂未保存成功。请稍后重试，保存完成后再进入错题整理。';else if(s.ackFailed)reply='模拟回执发送失败 · 原图已保存，题目不会丢失。回执可以单独重试，不会重复建题。';else reply='已保存 '+(s.reshoot?'2':'1')+' 张题目原图，正在按科目整理。你可以在网页错题库的“微信收题”中查看，核对题干后加入复习。';
html+='<div class="wx-message"><span class="wx-chat-avatar">知</span><div class="wx-bubble '+(s.ackFailed?'wx-bubble-warning':'')+'">'+reply+'</div></div>';
if(s.reshoot)html+='<div class="wx-message mine"><span class="wx-chat-avatar">我</span><div class="wx-bubble wx-attachment">'+icon('ImagePlus')+'<strong>清晰补拍 · 模拟附件</strong><span>补拍图和首次原图一起保留</span></div></div>';
if(['ready','imported'].includes(s.phase))html+='<div class="wx-chat-handoff">'+icon('ArrowRight')+'整理结果请到网页继续核对</div>';
return html;}
function wxCompose(s){if(s.phase==='idle')return '<button class="btn primary full" data-wx-action="send">'+icon('Send')+'模拟微信发来题图</button>';if(s.phase==='unlinked')return '<button class="btn full" data-wx-action="bind">模拟完成绑定，再发图</button>';if(s.phase==='ordinary')return '<button class="btn primary full" data-wx-action="explicit">附上 /错题，重新发图</button>';if(s.phase==='failed')return '<button class="btn primary full" data-wx-action="retry">'+icon('RotateCcw')+'重试接收这张图</button>';if(s.ackFailed)return '<button class="btn full" data-wx-action="retry-ack">只重试保存回执</button>';return '<button class="btn primary" data-wx-action="review">'+(s.phase==='ready'?'去网页核对':s.phase==='imported'?'查看同一错题':'查看网页收题进度')+' '+icon('ArrowRight')+'</button><button class="text-btn" data-wx-action="new">'+(s.phase==='imported'?'再收一道题':'重新演示')+'</button>';}
function wxSteps(s){const order=['已收到原图','识别整理','题干核对','统一学习记录'];const phase=s.phase;return '<div class="wx-steps">'+order.map((text,index)=>{const done=index===0||index===1&&['ready','blur','duplicate','imported'].includes(phase)||index===2&&phase==='imported'||index===3&&phase==='imported';return '<div class="'+(done?'done':'')+'"><span>'+icon(done?'Check':'Circle')+'</span>'+text+'</div>';}).join('')+'</div>';}
function wxMeta(s){const r=s.receipt;return '<div class="wx-receipt-meta"><span>'+icon('Link2')+'同一收题记录 · '+esc(r.id)+'</span><span>归属：'+esc(wxStudent(r.grade))+'自己的学习空间</span><span>来源：微信 · 小知 · 首次收到 '+esc(r.firstReceivedAt)+'</span><span>原图 '+(s.reshoot?'2':'1')+' 张'+(s.reshoot?'（首次图 + 清晰补拍）':'')+' · '+(s.phase==='saved'?'题目数量待整理':s.drafts.length+' 道题')+'</span></div>';}
function wxReceipt(s){if(['idle','ordinary','unlinked','failed'].includes(s.phase)){const text=s.phase==='unlinked'?['先完成绑定，再接收题目','归属不明确时不会写入任何孩子的学习空间。完成绑定后，需要重新发送照片。']:s.phase==='failed'?['还没有保存成功','接收失败不展示“原图已保存”，也不会创建可复习错题。重试后继续。']:s.phase==='ordinary'?['这张图还没有进入错题本','普通聊天和主动收题分开。可以开启收题模式，或附上 /错题 再发一次。']:['微信发来，网页继续','原图保存后，这里出现同一条记录。核对题干与标签，才进入今日复习。'];return '<div class="panel wx-await"><span class="wx-await-icon">'+icon(s.phase==='failed'?'TriangleAlert':'NotebookPen')+'</span><div class="eyebrow">CONTINUE ON THE WEB</div><h2>'+text[0]+'</h2><p>'+text[1]+'</p><div class="wx-boundaries"><span>'+icon('Image')+'原图可靠保存</span><span>'+icon('Tag')+'核对后打标</span><span>'+icon('CalendarCheck')+'接入同一复习计划</span></div><div class="callout">微信先负责收题，网页负责核对与学习。无需重复上传，也不在收到照片时判断“已掌握”。</div></div>';}
let body='<div class="panel"><div class="panel-head"><div><h2>网页 · 微信收题</h2><p>同一原图，同一条错题学习记录</p></div><span class="tag '+(s.phase==='imported'?'green':'amber')+'">'+({saved:'整理中',ready:'待核对',blur:'待补拍',duplicate:'重复原图',imported:'已关联错题库'}[s.phase])+'</span></div><div class="panel-pad">'+wxMeta(s)+wxSteps(s);
if(s.phase==='saved')body+='<div class="wx-processing"><h3>原图已保存，正在整理题干</h3><p>微信保存回执已'+(s.ackFailed?'暂时发送失败':'发出')+'；网页识别结果稍后更新，首次收到时间和孩子归属保持不变。</p><button class="btn primary" data-wx-action="organize">模拟整理完成 '+icon('ArrowRight')+'</button><button class="text-btn" data-wx-action="fail-ack">体验回执发送失败</button></div>';
if(s.phase==='blur')body+='<div class="callout">原图保留了，但题干有些看不清。暂不加入复习，也不猜测缺失内容。</div><button class="btn primary" data-wx-action="reshoot">'+icon('ImagePlus')+'模拟补发清晰题图</button><p class="mini-rule">本例演示同一错题补拍，首次收到时间和历史不变。真实产品需要明确关联原收题记录。</p>';
if(s.phase==='duplicate')body+='<div class="callout">'+esc(s.duplicateDescription||'本例重发预置已收录的原图。')+'这张完全相同的原图已经收过。本例将新来源关联到已有错题，保留已有标签、复习记录与下次安排。</div><button class="btn primary" data-wx-action="merge">关联已有错题记录 '+icon('Link2')+'</button><p class="mini-rule">当前实现按完全相同的图片内容去重；相似照片不自动视作同一原图。</p>';
if(['ready','imported'].includes(s.phase))body+=wxDraftForm(s);
return body+'</div></div><div class="wx-future-note">'+icon('CircleHelp')+'识别完成通知、每日复习提醒和微信直接答题属于后续方案。当前演示通过网页继续复习。</div>';}
function wxDraftForm(s){const drafts=s.drafts,d=drafts[s.selected]||drafts[0];if(!d)return '';const allDone=drafts.every(d=>d.questionId);let html='<div class="wx-question-tabs" aria-label="同图题目">'+drafts.map((item,i)=>'<button data-wx-draft="'+i+'" class="'+(s.selected===i?'active':'')+'">第 '+(i+1)+' 题'+(item.questionId?icon('Check'):'')+'</button>').join('')+'</div>';if(d.questionId){const q=questions.find(q=>q.id===d.questionId);html+='<div class="wx-confirmed"><div class="row between"><h3>'+esc(q.title)+'</h3>'+statusBadge(q)+'</div><div class="question-meta">'+tags(q)+'</div><div class="card-stem">'+esc(q.stem)+'</div><p class="aside-note">'+(activeStatus(q)?'已接入今日复习、同类变式和掌握档案。之后复习继续写入这道题，不另建一份微信历史。':q.status==='closed'?'这道题已掌握。本次只追加来源，不重新进入日常推荐；仍可主动抽检。':'这道题仍在暂停中。本次只追加来源，恢复前不进入日常推荐。')+'</p><div class="row wrap" style="margin-top:16px"><button class="btn" data-detail="'+q.id+'">错题详情与标签</button>'+(activeStatus(q)?'<button class="btn primary" data-practice="'+q.id+'">独立试一题 '+icon('ArrowRight')+'</button>':q.status==='closed'?'<button class="btn primary" data-spotcheck="'+q.id+'">抽检一下 '+icon('ArrowRight')+'</button>':'')+'</div></div>';if(allDone)html+='<div class="callout green">这张照片的 '+drafts.length+' 道题已全部核对或关联。日常推荐沿用各题当前学习状态。<br><button class="text-btn" data-go="today">查看今日复习 '+icon('ArrowRight')+'</button></div>';return html;}
html+='<p class="wx-review-intro">'+(drafts.length>1?'这张图拆成 '+drafts.length+' 道题，共享原图，分别核对和复习。':'先核对识别题干，再确认错因。')+'</p><div class="form-two"><label class="field">科目<select id="wx-subject">'+['待确认','数学','英语','语文'].map(v=>'<option '+(d.subject===v?'selected':'')+'>'+v+'</option>').join('')+'</select></label><label class="field">知识点<input id="wx-topic" value="'+esc(d.topic)+'"></label></div><label class="field">识别题干 · 预设示例<textarea id="wx-stem">'+esc(d.stem)+'</textarea></label><label class="field">我的错因与标签<input id="wx-tags" value="'+esc(d.tags.join(', '))+'" placeholder="例如：移项变号, 概念"></label><label class="checks"><input type="checkbox" id="wx-confirm"><span>已核对题干、科目与知识点，可以加入复习<br><span class="muted small-text">照片入库不代表系统已判错，更不代表已掌握。</span></span></label><button class="btn primary full" data-wx-action="confirm">核对本题并加入复习 '+icon('ArrowRight')+'</button><p class="mini-rule">仅演示已核对答案的预设题；修改题干后需要真实批改或人工确认，不能沿用示例答案。</p>';return html;}
function wxDrafts(g,scenario){const primary=g==='5';const first={key:'first',hint:primary?'先把 1/3 通分成分母为 6 的分数。':'先把等式两边同时减去 3。',variants:primary?{similar:{stem:'计算：1/4 + 1/8 = ?（请用最简分数填写）',answer:'3/8',solution:'1/4 = 2/8，2/8 + 1/8 = 3/8。',dimension:'更换分母和数值，验证通分方法',topic:'异分母分数加法'},advanced:structuredClone(INITIAL.find(q=>q.id==='p1').variants.advanced)}:undefined,subject:scenario==='subject'?'待确认':'数学',topic:primary?'异分母分数加法':'一元一次方程',tags:primary?['忘记通分','计算']:['移项变号','概念'],stem:primary?'计算：1/3 + 1/6 = ?（请用分数填写）':'解方程：2x + 3 = 11，x = ?',answer:primary?'1/2':'4',solution:primary?'1/3 = 2/6，和为 3/6 = 1/2。':'等式两边减去 3，得到 2x = 8，所以 x = 4。',template:primary?'p1':'m2'};if(scenario!=='multi')return [first];return [first,{key:'second',hint:primary?'先看两个因数一共有几位小数。':'先算乘法，再处理减去一个负数。',subject:'数学',topic:primary?'小数乘法':'有理数运算',tags:primary?['小数点','计算']:['去括号漏变号','计算'],stem:primary?'计算：0.2 × 0.5 = ?':'计算：−6 − 2 × (−5) = ?',answer:primary?'0.1':'4',solution:primary?'2 × 5 = 10，共两位小数，得到 0.10 = 0.1。':'−6 − (−10) = −6 + 10 = 4。',template:primary?'p2':'m1'}];}
function sendWx(explicit=false,retry=false){const s=wxState();s.lastExplicit=explicit;if(!wxLinked[grade]){s.phase='unlinked';render();return;}if(!wxAuto&&!explicit){s.phase='ordinary';render();return;}if(s.scenario==='failed'&&!retry){s.phase='failed';render();return;}if(s.scenario==='duplicate'){const latest=questions.findLast(q=>q.grade===grade&&q.source==='微信 · 小知');s.duplicateTargetIds=latest?questions.filter(q=>q.grade===grade&&q.receiptId===latest.receiptId).map(q=>q.id):[grade==='5'?'p1':'m2'];s.duplicateDescription=latest?'本例重发最近一次微信收录的原图。':'本例重发预置已收录的旧原图。';}s.receipt={id:'WX-'+grade+'-'+String(++wxSequence).padStart(3,'0'),grade,firstReceivedAt:'10/29 19:42',explicit};s.phase='saved';s.ackFailed=false;s.drafts=[];s.reshoot=false;render();toast('模拟原图已保存，尚未加入复习');}
function confirmWx(){const s=wxState(),r=s.receipt,d=s.drafts[s.selected];if(!r||r.grade!==grade||!d||d.questionId){toast('请在对应孩子的收题记录中继续');return;}if(!$('#wx-confirm').checked){toast('请先核对题干、科目与知识点，再勾选确认');$('#wx-confirm').focus();return;}if($('#wx-subject').value==='待确认'){toast('科目还没有确认，暂不加入复习');$('#wx-subject').focus();return;}const stem=$('#wx-stem').value.trim(),topic=$('#wx-topic').value.trim(),sub=$('#wx-subject').value;if(stem!==d.stem||topic!==d.topic||sub!=='数学'){toast('修改后的题目需要重新审核答案，本演示只支持原预设题进入练习');return;}const existing=questions.find(q=>q.grade===r.grade&&q.stem===stem);if(existing){d.questionId=existing.id;(existing.additionalSources??=[]).push({partner:'小知',receiptId:r.id,firstReceivedAt:r.firstReceivedAt});}else{const template=structuredClone(INITIAL.find(q=>q.id===d.template));const q={...template,id:'wx-'+r.id+'-'+d.key,title:topic+' · 微信收录',grade:r.grade,subject:sub,topic,stem,answer:d.answer,solution:d.solution,hint:d.hint,variants:d.variants||template.variants,tags:[...new Set($('#wx-tags').value.split(/[,，]/).map(t=>t.trim()).filter(Boolean))],created:TODAY,status:'open',due:TODAY,last:TODAY,stability:1,lapses:0,attempts:[],exposures:[],source:'微信 · 小知',receiptId:r.id,firstReceivedAt:r.firstReceivedAt,sourceImageCount:s.reshoot?2:1};delete q.closureEvidence;delete q.closedAt;questions.push(q);d.questionId=q.id;}
const next=s.drafts.findIndex(item=>!item.questionId);if(next<0)s.phase='imported';else s.selected=next;subject='全部';render();toast(existing?'已关联已有错题，保留学习历史':'已加入同一错题库与复习计划');}
function wxSettings(){modal={type:'wx-settings'};showModal('伙伴微信 · 收题设置','<div class="row between"><div><h2>小知 · 个人微信</h2><p class="aside-note">示例伙伴设置，只影响本页演示。</p></div><span class="tag">模拟连接</span></div><div class="wx-setting-row"><div><h3>自动收集绑定私聊的题图</h3><p>开启后发图即收。关闭时，图片消息附 /错题 或“加入错题本”单次收录。</p></div><label class="wx-toggle"><input id="wx-auto" type="checkbox" '+(wxAuto?'checked':'')+'><span>自动收题</span></label></div><div class="wx-setting-row"><div><h3>当前发图账号已绑定</h3><p>本例映射到 '+wxStudent()+'自己的学习空间。绑定与孩子归属不明时不收录，也不根据照片内容猜测。</p></div><label class="wx-toggle"><input id="wx-linked" type="checkbox" '+(wxLinked[grade]?'checked':'')+'><span>账号绑定</span></label></div><div class="callout">当前实现默认关闭自动收题，本例预先开启以方便体验。只收已绑定私聊；资料归发图者本人，不继承伙伴共享空间。</div><p class="aside-note">原图首次接收时确定归属。修改账号绑定或切换孩子，不会把旧照片移动到另一人的错题本。</p>','<p>无需扫码，本页不更改真实伙伴配置。</p><span class="spacer"></span><button class="btn primary" id="wx-save-settings">保存演示设置</button>');}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;if(b.dataset.wxInput){wxInput=b.dataset.wxInput;render();return;}if(b.dataset.wxScenario){const s=wxState();Object.assign(s,{scenario:b.dataset.wxScenario,phase:'idle',receipt:null,drafts:[],selected:0,ackFailed:false,reshoot:false});render();return;}if(b.dataset.wxDraft!==undefined){wxState().selected=Number(b.dataset.wxDraft);render();return;}if(['wx-settings','wx-settings-inline'].includes(b.id)){wxSettings();return;}if(b.id==='wx-save-settings'){wxAuto=$('#wx-auto').checked;wxLinked[grade]=$('#wx-linked').checked;closeModal();render();toast('演示收题设置已保存');return;}
const action=b.dataset.wxAction;if(!action)return;const s=wxState();switch(action){case 'send':sendWx();break;case 'explicit':sendWx(true);break;case 'retry':sendWx(!!s.lastExplicit,true);break;case 'bind':wxLinked[grade]=true;s.phase='idle';render();toast('模拟绑定完成，请重新发送题图');break;case 'review':$('#wx-web-side').focus({preventScroll:true});$('#wx-web-side').scrollIntoView({block:'start',behavior:'smooth'});break;case 'new':s.phase='idle';s.receipt=null;s.drafts=[];s.ackFailed=false;s.reshoot=false;render();break;case 'organize':s.drafts=s.scenario==='duplicate'?s.duplicateTargetIds.map(id=>({targetId:id})):wxDrafts(grade,s.scenario);s.selected=0;s.phase=s.scenario==='blur'?'blur':s.scenario==='duplicate'?'duplicate':'ready';render();break;case 'reshoot':s.reshoot=true;s.drafts=wxDrafts(grade,'clear');s.phase='ready';render();toast('首次原图与补拍图保留在同一记录');break;case 'fail-ack':s.ackFailed=true;render();break;case 'retry-ack':s.ackFailed=false;render();toast('已重试保存回执，未重复创建题目');break;case 'confirm':confirmWx();break;case 'merge':{const targets=s.duplicateTargetIds.map(id=>questions.find(q=>q.id===id)).filter(Boolean);for(const q of targets){(q.additionalSources??=[]).push({partner:'小知',receiptId:s.receipt.id,firstReceivedAt:s.receipt.firstReceivedAt});}s.drafts=targets.map(q=>({questionId:q.id}));s.selected=0;s.phase='imported';render();toast('来源已关联，原有标签、状态与复习历史保留');break;}}});
